CREATE TABLE "ActionQueueState" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"itemKey" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"snoozedUntil" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"dismissedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ActionQueueState_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "ActionQueueState_userId_itemKey_key" ON "ActionQueueState"("userId","itemKey");CREATE INDEX "ActionQueueState_userId_status_snoozedUntil_idx" ON "ActionQueueState"("userId","status","snoozedUntil");